def slots(start,end,names,good):
    if not start or not end:return []
    d=(end-start)/8
    return [{"slot":i+1,"name":name,"nature":"Good" if name in good else "Bad","time":f"{(a:=start+d*i).strftime('%I:%M %p')} - {(a+d).strftime('%I:%M %p')}"} for i,name in enumerate(names)]

def config(state):
    return STATE_CONFIGS.get(state.upper(),STATE_CONFIGS["KA"])

def regional_timings(sunrise,sunset,weekday,state):
    c=config(state); r={"system":c["system"],"muhurat_system":c["muhurat"],"calendar_style":c["style"],"layout":"row_weekday" if c["style"] in ROW_WEEKDAY_STYLES else "col_weekday","accent":c["accent"],"priority_fields":c["priority_fields"]}
    if c["muhurat"]=="Choghadiya":r["choghadiya_day"]=slots(sunrise,sunset,CHOGHADIYA[weekday],GOOD_C)
    elif c["muhurat"]=="Gowri":r["gowri_panchangam"]=slots(sunrise,sunset,GOWRI[weekday],GOOD_G)
    return r

def regional_month_name(state,month):
    style=config(state)["style"]
    names=REGIONAL_MONTHS.get(style) or REGIONAL_MONTHS.get("hindi")
    return names[(month-1)%12]

def available_states():return STATE_CONFIGS
def state_style(state_code):return config(state_code)["style"]
